const input = $input.first().json.body || $input.first().json;
const budget = Array.isArray(input.budgetCategories) ? input.budgetCategories.map(x => ({ category: x.category, planned: Number(x.planned || 0), actual: Number(x.actual || 0) })) : [];
const holdings = Array.isArray(input.holdings) ? input.holdings.map(x => ({ assetType: x.assetType || 'unspecified', label: x.label || 'holding', value: Number(x.value || 0), allocationPercent: Number(x.allocationPercent || 0), asOfDate: x.asOfDate || null })) : [];
const cashflow = { income: Number(input.periodIncome || 0), expenses: Number(input.periodExpenses || 0), net: Number(input.periodIncome || 0) - Number(input.periodExpenses || 0) };
const prompt = `Provide a neutral, educational summary of this user's supplied aggregate budget and investment allocation. Explain observed budget variances and diversification concepts at a general level; identify missing or stale valuation dates. Do not recommend buying, selling, holding, specific products, or target allocations; do not forecast returns or imply guarantees. This is not financial advice. Avoid requesting identifiers, account numbers, credentials, or exact statements. Return JSON keys summary (string), budgetObservations (array), generalEducation (array), dataLimitations (array), consultQualifiedAdvisor (boolean).
${JSON.stringify({ budget, holdings, cashflow })}`;
return [{ json: { budget, holdings, cashflow, prompt } }];

const response = $input.first().json;
const source = $('Prepare Anonymized Finance View').first().json;
let education;
try { education = JSON.parse(response.candidates[0].content.parts[0].text); } catch { education = { summary: 'Unable to generate a summary. Review your figures directly.', budgetObservations: [], generalEducation: [], dataLimitations: ['AI response could not be parsed.'], consultQualifiedAdvisor: true }; }
return [{ json: { status: 'education_ready', cashflow: source.cashflow, budgetCategories: source.budget, holdingsSummary: source.holdings, education, financialAdvice: false, transactionsExecuted: false } }];
